// MIT native validation host.
#include <cuda_runtime.h>
#include <cstdio>
#include "texture-helpers.cu"
#define CHECK(x) do{auto e=(x);if(e!=cudaSuccess){printf("CUDA ERROR %s\n",cudaGetErrorString(e));return 2;}}while(0)
int main(){float data[2][4]={{1,2,3,4},{10,20,30,40}},expected[]={210,370,580,790,120,215,335,455},result[8];cudaArray_t arrays[2];cudaTextureObject_t textures[2];auto channel=cudaCreateChannelDesc<float>();for(int i=0;i<2;i++){CHECK(cudaMallocArray(&arrays[i],&channel,4,1));CHECK(cudaMemcpyToArray(arrays[i],0,0,data[i],16,cudaMemcpyHostToDevice));cudaResourceDesc resource={};resource.resType=cudaResourceTypeArray;resource.res.array.array=arrays[i];cudaTextureDesc desc={};desc.normalizedCoords=1;desc.filterMode=i?cudaFilterModeLinear:cudaFilterModePoint;desc.readMode=cudaReadModeElementType;desc.addressMode[0]=desc.addressMode[1]=cudaAddressModeClamp;CHECK(cudaCreateTextureObject(&textures[i],&resource,&desc,nullptr));}float* output;CHECK(cudaMalloc(&output,32));textureHelpers<<<1,4>>>(output,textures[0],textures[1]);CHECK(cudaGetLastError());CHECK(cudaDeviceSynchronize());CHECK(cudaMemcpy(result,output,32,cudaMemcpyDeviceToHost));for(int i=0;i<8;i++)if(result[i]!=expected[i]){printf("FAIL component=%d actual=%g expected=%g\n",i,result[i],expected[i]);return 1;}for(int i=0;i<2;i++){CHECK(cudaDestroyTextureObject(textures[i]));CHECK(cudaFreeArray(arrays[i]));}CHECK(cudaFree(output));printf("PASS native texture helper forwarding: all eight values exact; distinct images, nearest/linear samplers, swapped arguments and descending templates\n");return 0;}
